"""Course model built from a mesh (e.g. the official DroneHacks OBJ).

Everything here is derived from geometry, with group names used only as
optional *hints* (launch mark, landing pad, guideline). Nothing is
hard-coded to the 2026 layout, so a different course file produces a
different plan.

Frames: the model frame of the official course is metres, origin at the
floor centre, +X east, +Y north, +Z up. We use it directly as the "map"
frame (ENU-like).
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Dict, List, Optional, Tuple

import numpy as np

from .mesh import MeshGroup, load_obj

MARKING_MAX_Z = 0.01      # anything entirely below 1 cm is a floor marking
THIN_PLANE = 0.01         # net planes are ~1.3 mm thick


@dataclass
class Aperture:
    """A rectangular hole through a wall (e.g. the window)."""
    group: str
    center: np.ndarray        # (3,) map frame, metres
    normal: np.ndarray        # (2,) unit, horizontal, arbitrary sign
    along: np.ndarray         # (2,) unit, along the wall
    width: float
    z_min: float
    z_max: float

    def waypoints(self, standoff: float) -> Tuple[np.ndarray, np.ndarray]:
        """Two points on either side of the hole, at mid-height."""
        zc = 0.5 * (self.z_min + self.z_max)
        c = np.array([self.center[0], self.center[1], zc])
        n = np.array([self.normal[0], self.normal[1], 0.0])
        return c - standoff * n, c + standoff * n


@dataclass
class Course:
    groups: Dict[str, MeshGroup]
    obstacles: List[str]
    markings: List[str]
    boundary: List[str]
    floor: List[str]
    bounds_min: np.ndarray
    bounds_max: np.ndarray
    wall_height: float
    launch: Optional[np.ndarray] = None
    pad_center: Optional[np.ndarray] = None
    pad_radius: Optional[float] = None
    guideline: Optional[np.ndarray] = None     # (N,2) ordered centreline
    apertures: List[Aperture] = field(default_factory=list)

    # ------------------------------------------------------------------ build
    @classmethod
    def from_obj(cls, path: str, hints: Optional[dict] = None) -> "Course":
        return cls.from_groups(load_obj(path), hints)

    @classmethod
    def from_groups(cls, groups: Dict[str, MeshGroup], hints: Optional[dict] = None) -> "Course":
        hints = hints or {}
        all_pts = np.concatenate([g.triangles.reshape(-1, 3) for g in groups.values()])
        bmin, bmax = all_pts.min(axis=0), all_pts.max(axis=0)
        obstacles, markings, boundary, floor = [], [], [], []
        for name, g in groups.items():
            lo, hi = g.bbox
            ext = hi - lo
            lname = name.lower()
            if hi[2] <= MARKING_MAX_Z and ext[0] * ext[1] > 0.5 * (bmax[0] - bmin[0]) * (bmax[1] - bmin[1]):
                floor.append(name)
            elif hi[2] <= MARKING_MAX_Z:
                markings.append(name)
            elif "net" in lname or (min(ext[0], ext[1]) < THIN_PLANE and
                                     (np.isclose(lo[0], bmin[0], atol=0.02) or np.isclose(hi[0], bmax[0], atol=0.02) or
                                      np.isclose(lo[1], bmin[1], atol=0.02) or np.isclose(hi[1], bmax[1], atol=0.02))) \
                    or ext[2] < THIN_PLANE and lo[2] > 1.0:
                boundary.append(name)
            else:
                obstacles.append(name)
        # Wall height = most common max-Z among box-like obstacles (8 vertices).
        tops = [round(float(groups[n].bbox[1][2]), 3) for n in obstacles if len(groups[n].vertices) <= 16]
        wall_h = float(max(set(tops), key=tops.count)) if tops else float(hints.get("wall_height", 1.7272))
        c = cls(groups, obstacles, markings, boundary, floor, bmin, bmax, wall_h)
        c._find_semantics(hints)
        return c

    def _find_semantics(self, hints: dict) -> None:
        def pick(substrs, pool):
            for n in pool:
                if any(s in n.lower() for s in substrs):
                    return n
            return None

        n = hints.get("launch_group") or pick(["launch", "start"], self.markings)
        if "launch_xy" in hints:
            self.launch = np.array([*hints["launch_xy"], 0.0])
        elif n:
            lo, hi = self.groups[n].bbox
            self.launch = np.array([(lo[0] + hi[0]) / 2, (lo[1] + hi[1]) / 2, 0.0])

        pads = [m for m in self.markings if "pad" in m.lower() and "cross" not in m.lower()]
        if "pad_xy" in hints:
            self.pad_center = np.array([*hints["pad_xy"], 0.0])
            self.pad_radius = float(hints.get("pad_radius", 0.76))
        elif pads:
            # the pad itself = the pad marking whose extent is largest but < 2.5 m
            best = None
            for m in pads:
                lo, hi = self.groups[m].bbox
                r = 0.5 * max(hi[0] - lo[0], hi[1] - lo[1])
                if r < 1.25 and (best is None or r > best[1]):
                    best = (m, r, lo, hi)
            if best:
                _, r, lo, hi = best
                self.pad_center = np.array([(lo[0] + hi[0]) / 2, (lo[1] + hi[1]) / 2, 0.0])
                self.pad_radius = r

        g = hints.get("guideline_group") or pick(["guide", "line"], self.markings)
        if g:
            self.guideline = _strip_centreline(self.groups[g])

        for name in self.obstacles:
            ap = _find_hole(name, self.groups[name])
            if ap is not None:
                self.apertures.append(ap)

    # ------------------------------------------------------------ rasterise
    def occupancy(self, res: float, z_lo: float, z_hi: float,
                  include_boundary: bool = True) -> "Grid2D":
        """Cells whose column contains obstacle geometry inside [z_lo, z_hi]."""
        grid = Grid2D.empty(self.bounds_min[:2], self.bounds_max[:2], res)
        names = self.obstacles + (self.boundary if include_boundary else [])
        for name in names:
            tri = self.groups[name].triangles
            zmin = tri[:, :, 2].min(axis=1)
            zmax = tri[:, :, 2].max(axis=1)
            sel = tri[(zmax >= z_lo) & (zmin <= z_hi)]
            if len(sel) > DENSE_MESH_TRIS and _is_convex_blob(self.groups[name]):
                # finely tessellated solid (e.g. a boulder): fill the convex hull of its slice once
                pts = [np.asarray(p)[:2] for t in sel for p in _clip_z(t, z_lo, z_hi)]
                if len(pts) >= 3:
                    grid.fill_polygon(_convex_hull(np.array(pts)))
                continue
            for t in sel:
                poly = _clip_z(t, z_lo, z_hi)
                if len(poly) >= 2:
                    grid.fill_polygon(np.asarray(poly)[:, :2])
        if include_boundary:
            grid.occ[0, :] = grid.occ[-1, :] = True
            grid.occ[:, 0] = grid.occ[:, -1] = True
        return grid


# --------------------------------------------------------------------- grid
@dataclass
class Grid2D:
    origin: np.ndarray   # (2,) world xy of cell (0,0) corner
    res: float
    occ: np.ndarray      # (ny, nx) bool, row = y index

    @classmethod
    def empty(cls, lo, hi, res):
        nx = int(np.ceil((hi[0] - lo[0]) / res))
        ny = int(np.ceil((hi[1] - lo[1]) / res))
        return cls(np.asarray(lo, float), res, np.zeros((ny, nx), dtype=bool))

    @property
    def shape(self):
        return self.occ.shape

    def to_cell(self, xy) -> Tuple[int, int]:
        ij = np.floor((np.asarray(xy[:2]) - self.origin) / self.res).astype(int)
        return int(np.clip(ij[1], 0, self.occ.shape[0] - 1)), int(np.clip(ij[0], 0, self.occ.shape[1] - 1))

    def to_world(self, r: int, c: int) -> np.ndarray:
        return self.origin + (np.array([c, r]) + 0.5) * self.res

    def fill_polygon(self, pts: np.ndarray) -> None:
        ny, nx = self.occ.shape
        # always rasterise the outline (catches degenerate/vertical faces)
        for a, b in zip(pts, np.roll(pts, -1, axis=0)):
            n = max(2, int(np.ceil(np.linalg.norm(b - a) / (0.5 * self.res))) + 1)
            seg = a + np.linspace(0, 1, n)[:, None] * (b - a)
            ij = np.floor((seg - self.origin) / self.res).astype(int)
            ok = (ij[:, 0] >= 0) & (ij[:, 0] < nx) & (ij[:, 1] >= 0) & (ij[:, 1] < ny)
            self.occ[ij[ok, 1], ij[ok, 0]] = True
        if len(pts) < 3:
            return
        lo = np.floor((pts.min(axis=0) - self.origin) / self.res).astype(int)
        hi = np.ceil((pts.max(axis=0) - self.origin) / self.res).astype(int)
        lo = np.clip(lo, 0, [nx - 1, ny - 1]); hi = np.clip(hi, 0, [nx, ny])
        if hi[0] - lo[0] < 1 or hi[1] - lo[1] < 1:
            return
        cx = self.origin[0] + (np.arange(lo[0], hi[0]) + 0.5) * self.res
        cy = self.origin[1] + (np.arange(lo[1], hi[1]) + 0.5) * self.res
        X, Y = np.meshgrid(cx, cy)
        inside = _points_in_poly(X.ravel(), Y.ravel(), pts).reshape(X.shape)
        self.occ[lo[1]:hi[1], lo[0]:hi[0]] |= inside

    def distance(self) -> np.ndarray:
        """Euclidean distance (m) from each cell centre to the nearest occupied cell."""
        if not self.occ.any():
            return np.full(self.occ.shape, np.inf)
        try:  # SciPy is in the Isaac ROS base image
            from scipy.ndimage import distance_transform_edt
            return distance_transform_edt(~self.occ) * self.res
        except ImportError:
            return np.sqrt(_edt_sq(self.occ)) * self.res

    def inflate(self, radius: float) -> "Grid2D":
        return Grid2D(self.origin.copy(), self.res, self.distance() <= radius)

    def closed(self, radius: float) -> "Grid2D":
        """Morphological closing: fills the hollow between the two faces of thin walls.

        A mesh slice gives each 4-in wall as two parallel outlines; scan matching
        against that would have two equally good solutions 10 cm apart.
        """
        dil = self.distance() <= radius
        inv = Grid2D(self.origin.copy(), self.res, ~dil)
        return Grid2D(self.origin.copy(), self.res, ~(inv.distance() <= radius))


# ---------------------------------------------------------------- helpers
DENSE_MESH_TRIS = 2000


def _is_convex_blob(g: MeshGroup) -> bool:
    """Heuristic: a dense mesh whose footprint is ~round and filled (a boulder), not a hollow tube."""
    lo, hi = g.bbox
    ext = hi[:2] - lo[:2]
    if min(ext) <= 0 or max(ext) / min(ext) > 1.5:
        return False
    c = 0.5 * (lo[:2] + hi[:2])
    v = g.vertices
    top = v[v[:, 2] > lo[2] + 0.8 * (hi[2] - lo[2])]
    # a solid dome has vertices near its axis at the top; a hollow tube does not
    return len(top) > 0 and np.min(np.linalg.norm(top[:, :2] - c, axis=1)) < 0.25 * min(ext)


def _convex_hull(pts: np.ndarray) -> np.ndarray:
    """Andrew's monotone chain."""
    P = np.unique(np.round(pts, 6), axis=0)
    if len(P) < 3:
        return P
    P = P[np.lexsort((P[:, 1], P[:, 0]))]
    cross = lambda o, a, b: (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])
    lower, upper = [], []
    for p in P:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    for p in P[::-1]:
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    return np.array(lower[:-1] + upper[:-1])


def _edt_1d(f: np.ndarray) -> np.ndarray:
    """Felzenszwalb & Huttenlocher (2012) 1-D squared distance transform."""
    n = len(f)
    d = np.empty(n)
    v = np.zeros(n, dtype=int)
    z = np.empty(n + 1)
    k = 0
    z[0], z[1] = -np.inf, np.inf
    for q in range(1, n):
        while True:
            s = ((f[q] + q * q) - (f[v[k]] + v[k] * v[k])) / (2 * q - 2 * v[k])
            if s <= z[k]:
                k -= 1
                if k < 0:
                    k = 0
                    break
            else:
                break
        k += 1
        v[k] = q
        z[k] = s
        z[k + 1] = np.inf
    k = 0
    for q in range(n):
        while z[k + 1] < q:
            k += 1
        d[q] = (q - v[k]) ** 2 + f[v[k]]
    return d


def _edt_sq(occ: np.ndarray) -> np.ndarray:
    """Exact squared Euclidean distance (cells) to the nearest True cell (pure numpy/Python)."""
    INF = 1e12
    f = np.where(occ, 0.0, INF)
    tmp = np.empty_like(f)
    for c in range(f.shape[1]):
        tmp[:, c] = _edt_1d(f[:, c])
    out = np.empty_like(f)
    for r in range(f.shape[0]):
        out[r, :] = _edt_1d(tmp[r, :])
    return out


def _points_in_poly(x, y, poly):
    inside = np.zeros(len(x), dtype=bool)
    px, py = poly[:, 0], poly[:, 1]
    j = len(poly) - 1
    for i in range(len(poly)):
        cond = ((py[i] > y) != (py[j] > y))
        with np.errstate(divide="ignore", invalid="ignore"):
            xint = (px[j] - px[i]) * (y - py[i]) / (py[j] - py[i] + 1e-12) + px[i]
        inside ^= cond & (x < xint)
        j = i
    return inside


def _clip_z(tri: np.ndarray, z_lo: float, z_hi: float) -> List[np.ndarray]:
    poly = [p for p in tri]
    for z0, keep_above in ((z_lo, True), (z_hi, False)):
        out = []
        n = len(poly)
        for k in range(n):
            a, b = poly[k], poly[(k + 1) % n]
            ina = a[2] >= z0 if keep_above else a[2] <= z0
            inb = b[2] >= z0 if keep_above else b[2] <= z0
            if ina:
                out.append(a)
            if ina != inb and abs(b[2] - a[2]) > 1e-12:
                t = (z0 - a[2]) / (b[2] - a[2])
                out.append(a + t * (b - a))
        poly = out
        if not poly:
            return []
    return poly


def _find_hole(name: str, g: MeshGroup) -> Optional[Aperture]:
    """Detect a rectangular through-hole in a slab-like wall group."""
    v = g.vertices
    if len(v) <= 8 or len(v) > 64:
        return None
    xy = v[:, :2]
    m = xy.mean(axis=0)
    cov = np.cov((xy - m).T)
    w, vec = np.linalg.eigh(cov)
    along = vec[:, 1]; normal = vec[:, 0]
    s = (xy - m) @ along
    z = v[:, 2]
    s_lo, s_hi, z_lo, z_hi = s.min(), s.max(), z.min(), z.max()
    tol = 1e-3
    interior = (s > s_lo + tol) & (s < s_hi - tol) & (z > z_lo + tol) & (z < z_hi - tol)
    if interior.sum() < 4:
        return None
    hs, hz = s[interior], z[interior]
    c_s = 0.5 * (hs.min() + hs.max())
    t_mid = ((xy - m) @ normal)
    centre_xy = m + c_s * along + 0.5 * (t_mid.min() + t_mid.max()) * normal
    return Aperture(group=name, center=np.array([centre_xy[0], centre_xy[1], 0.5 * (hz.min() + hz.max())]),
                    normal=normal, along=along, width=float(hs.max() - hs.min()),
                    z_min=float(hz.min()), z_max=float(hz.max()))


def _strip_centreline(g: MeshGroup, step: float = 0.06) -> np.ndarray:
    """Ordered centreline of a thin floor strip (polyline of a painted line)."""
    tri = g.triangles[:, :, :2]
    lo, hi = tri.reshape(-1, 2).min(0), tri.reshape(-1, 2).max(0)
    grid = Grid2D.empty(lo - step, hi + step, step)
    for t in tri:
        grid.fill_polygon(t)
    pts = np.array([grid.to_world(r, c) for r, c in np.argwhere(grid.occ)])
    if len(pts) < 2:
        return pts
    # greedy nearest-neighbour ordering from an endpoint, then decimate
    start = pts[np.argmax(np.linalg.norm(pts - pts.mean(0), axis=1))]
    order = [start]
    remaining = pts.copy()
    cur = start
    while len(remaining):
        d = np.linalg.norm(remaining - cur, axis=1)
        k = int(np.argmin(d))
        if d[k] > 5 * step:
            break
        cur = remaining[k]
        remaining = np.delete(remaining, np.where(d < 1.5 * step)[0], axis=0)
        order.append(cur)
    line = np.array(order)
    return _rdp(line, 0.5 * step)


def _rdp(pts: np.ndarray, eps: float) -> np.ndarray:
    if len(pts) < 3:
        return pts
    a, b = pts[0], pts[-1]
    ab = b - a
    nrm = np.linalg.norm(ab) + 1e-12
    rel = pts - a
    d = np.abs(ab[0] * rel[:, 1] - ab[1] * rel[:, 0]) / nrm
    k = int(np.argmax(d))
    if d[k] > eps:
        return np.vstack([_rdp(pts[:k + 1], eps)[:-1], _rdp(pts[k:], eps)])
    return np.array([a, b])
